function [pn_struct,selection_s]=select_pn_profile(pn_profile_s,fc_Hz,mode)
% Generated by GitHub Copilot under Lance Lascari's direction.
% Return a legacy point. Interpolation is opt-in and never extrapolates.

if nargin<3
    mode='exact';
end
validate_pn_profile(pn_profile_s);
validateattributes(fc_Hz,{'numeric'},{'real','finite','scalar','positive'});
if ~ischar(mode) || ~any(strcmp(mode,{'exact','interpolate'}))
    error('pn_profile:InvalidMode','Selection mode must be exact or interpolate.');
end
points=pn_profile_s.points;
carriers=[points.fc];
index=find(carriers==fc_Hz,1);
if ~isempty(index)
    pn_struct=points(index);
    selection_s=struct('mode','exact','indices',index,'weights',1, ...
        'offset_range_Hz',[pn_struct.f(1) pn_struct.f(end)]);
    return;
end
if fc_Hz<carriers(1) || fc_Hz>carriers(end)
    error('pn_profile:Extrapolation','Requested carrier is outside the characterized frequency range.');
end
if strcmp(mode,'exact')
    error('pn_profile:NoExactPoint','No exact carrier point; explicitly request interpolate to model it.');
end

lower=find(carriers<fc_Hz,1,'last');
upper=lower+1;
a=points(lower);
b=points(upper);
offset_min=max(a.f(1),b.f(1));
offset_max=min(a.f(end),b.f(end));
if offset_min>=offset_max
    error('pn_profile:NoCommonOffsets','Bracketing curves have no usable shared offset range.');
end
offsets=unique([a.f b.f]);
offsets=offsets(offsets>=offset_min & offsets<=offset_max);
noise_a=interp1(log10(a.f),a.n,log10(offsets),'linear');
noise_b=interp1(log10(b.f),b.n,log10(offsets),'linear');
weight=(fc_Hz-a.fc)/(b.fc-a.fc);
% Relative powers avoid underflow while retaining linear-power interpolation.
noise_scale=max(noise_a,noise_b);
noise=noise_scale+10*log10((1-weight)*10.^((noise_a-noise_scale)/10) + ...
    weight*10.^((noise_b-noise_scale)/10));
kvco=(1-weight)*a.kvco+weight*b.kvco;
comment=sprintf(['MODELED: carrier interpolation between %.12g and %.12g Hz; ' ...
    'Kvco linear, noise linear power, offset interpolation dBc/Hz versus log10(Hz). ' ...
    'Source: %s | Lower: %s | Upper: %s'],a.fc,b.fc,pn_profile_s.source,a.comment,b.comment);
pn_struct=build_pn_struct(fc_Hz,kvco,offsets,noise,comment, ...
    sprintf('pn_profile_%.12g_Hz',fc_Hz));
selection_s=struct('mode','interpolate','indices',[lower upper], ...
    'weights',[1-weight weight],'offset_range_Hz',[offset_min offset_max]);
end
